import json


class ImportProblem(Exception):
    def __init__(self, line, message='invalid line'):
        self.line = line
        super().__init__(f'invalid line {line}: {message}')


def _validate_line(raw, line_no):
    if not raw.strip():
        return None
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise ImportProblem(line_no, 'malformed UTF-8') from None
    try:
        record = json.loads(text)
    except ValueError:
        raise ImportProblem(line_no, 'malformed JSON') from None
    if not isinstance(record, dict):
        raise ImportProblem(line_no, 'record must be an object')
    record_id = record.get('id')
    if not isinstance(record_id, str) or not record_id:
        raise ImportProblem(line_no, 'missing or invalid id')
    record_count = record.get('count')
    if isinstance(record_count, bool) or not isinstance(record_count, int):
        raise ImportProblem(line_no, 'missing or invalid count')
    return record


def import_bytes(payload, store):
    # Validate every line before touching the store, so a failure at line N
    # leaves previously parsed records uncommitted (no half import).
    records = []
    for line_no, raw in enumerate(payload.splitlines(), 1):
        record = _validate_line(raw, line_no)
        if record is not None:
            records.append(record)
    count = len(records)
    for record in records:
        store.append(record)
    return count

